def transform(grid):
    h, w = len(grid), len(grid[0])
    candidates = []
    for r in range(h - 2):
        for c in range(w - 2):
            patch = [row[c:c + 3] for row in grid[r:r + 3]]
            colors = {v for row in patch for v in row}
            if 0 not in colors and len(colors) == 3:
                candidates.append(patch)
    if len(candidates) != 1:
        raise ValueError(f'Expected one 3x3, three-color patch; got {len(candidates)}')
    return candidates[0]

